"use strict";(self.webpackChunkdocusaurus=self.webpackChunkdocusaurus||[]).push([["2105"],{1922(e,n,s){s.r(n),s.d(n,{metadata:()=>t,default:()=>u,frontMatter:()=>a,contentTitle:()=>o,toc:()=>c,assets:()=>l});var t=JSON.parse('{"id":"artie-case-study","title":"Conception d\u2019un assistant de documentation bas\xe9 sur l\u2019IA","description":"\xc9tude de cas sur la conception d\'Artie, un assistant de documentation bas\xe9 sur l\'IA.","source":"@site/i18n/fr/docusaurus-plugin-content-docs/current/artie-case-study.md","sourceDirName":".","slug":"/artie-case-study","permalink":"/software/fr/docs/artie-case-study","draft":false,"unlisted":false,"tags":[],"version":"current","sidebarPosition":7,"frontMatter":{"id":"artie-case-study","title":"Conception d\u2019un assistant de documentation bas\xe9 sur l\u2019IA","sidebar_label":"\xc9tude de cas sur l\'assistant IA","sidebar_position":7,"slug":"artie-case-study","description":"\xc9tude de cas sur la conception d\'Artie, un assistant de documentation bas\xe9 sur l\'IA."},"sidebar":"tutorialSidebar","previous":{"title":"Workflow Microsoft Word vers GitHub Wiki avec Writage","permalink":"/software/fr/docs/word-github-wiki-writage"}}'),i=s(4848),r=s(8453);let a={id:"artie-case-study",title:"Conception d\u2019un assistant de documentation bas\xe9 sur l\u2019IA",sidebar_label:"\xc9tude de cas sur l'assistant IA",sidebar_position:7,slug:"artie-case-study",description:"\xc9tude de cas sur la conception d'Artie, un assistant de documentation bas\xe9 sur l'IA."},o="Conception d\u2019un assistant de documentation bas\xe9 sur l\u2019IA",l={},c=[{value:"Acheminement des publics",id:"acheminement-des-publics",level:2},{value:"Ancrage et extraction des connaissances",id:"ancrage-et-extraction-des-connaissances",level:2},{value:"Personnalit\xe9 et adaptation du ton",id:"personnalit\xe9-et-adaptation-du-ton",level:2},{value:"S\xe9curit\xe9 et garde-fous",id:"s\xe9curit\xe9-et-garde-fous",level:2},{value:"Protection contre l\u2019injection de prompt",id:"protection-contre-linjection-de-prompt",level:3},{value:"Restriction du champ d\u2019application",id:"restriction-du-champ-dapplication",level:3},{value:"Confidentialit\xe9 des donn\xe9es",id:"confidentialit\xe9-des-donn\xe9es",level:3},{value:"Limites professionnelles",id:"limites-professionnelles",level:3},{value:"\xab Easter eggs \xbb contr\xf4l\xe9s",id:"-easter-eggs--contr\xf4l\xe9s",level:2},{value:"Ce que je ferais diff\xe9remment",id:"ce-que-je-ferais-diff\xe9remment",level:2}];function d(e){let n={a:"a",em:"em",h1:"h1",h2:"h2",h3:"h3",header:"header",hr:"hr",li:"li",p:"p",strong:"strong",ul:"ul",...(0,r.R)(),...e.components};return(0,i.jsxs)(i.Fragment,{children:[(0,i.jsx)(n.header,{children:(0,i.jsx)(n.h1,{id:"conception-dun-assistant-de-documentation-bas\xe9-sur-lia",children:"Conception d\u2019un assistant de documentation bas\xe9 sur l\u2019IA"})}),"\n",(0,i.jsxs)(n.p,{children:["Cette \xe9tude de cas pr\xe9sente les choix de conception qui ont pr\xe9sid\xe9 \xe0 la cr\xe9ation d\u2019",(0,i.jsx)(n.strong,{children:"Artie"}),", l\u2019assistant IA int\xe9gr\xe9 \xe0 ce site de documentation. Artie est un assistant de type \xab retrieval-augmented generation \xbb (RAG), con\xe7u pour r\xe9pondre \xe0 des questions en s\u2019appuyant uniquement sur le contenu publi\xe9 ici. Il n\u2019a pas acc\xe8s \xe0 des connaissances g\xe9n\xe9rales et ne g\xe9n\xe9rera pas de liens fantaisistes ni de fonctionnalit\xe9s invent\xe9es de toutes pi\xe8ces."]}),"\n",(0,i.jsx)(n.p,{children:"La cr\xe9ation d\u2019un assistant de documentation semble simple jusqu\u2019\xe0 ce que l\u2019on prenne en compte les cas limites : que se passe-t-il lorsque quelqu\u2019un pose une question qui n\u2019est pas trait\xe9e dans la documentation ? Que faire si deux publics distincts utilisent la m\xeame interface ? Comment doter une IA d\u2019une personnalit\xe9 sans qu\u2019elle divague ? Et comment emp\xeacher quelqu\u2019un de d\xe9tourner compl\xe8tement la requ\xeate ?"}),"\n",(0,i.jsx)(n.p,{children:"Cette page explique comment chacun de ces probl\xe8mes a \xe9t\xe9 r\xe9solu."}),"\n",(0,i.jsx)(n.hr,{}),"\n",(0,i.jsx)(n.h2,{id:"acheminement-des-publics",children:"Acheminement des publics"}),"\n",(0,i.jsx)(n.p,{children:"Artie s\u2019adresse \xe0 deux publics via une seule interface conversationnelle :"}),"\n",(0,i.jsxs)(n.ul,{children:["\n",(0,i.jsxs)(n.li,{children:[(0,i.jsx)(n.strong,{children:"Les d\xe9veloppeurs et les utilisateurs finaux"})," \xe0 la recherche d\u2019instructions de configuration, de r\xe9f\xe9rences API ou d\u2019explications sur les exemples de la documentation."]}),"\n",(0,i.jsxs)(n.li,{children:[(0,i.jsx)(n.strong,{children:"Les recruteurs et les responsables du recrutement"})," qui \xe9valuent ce portfolio et peuvent poser des questions sur les qualifications, l\u2019exp\xe9rience ou le processus de r\xe9daction."]}),"\n"]}),"\n",(0,i.jsx)(n.p,{children:"Plut\xf4t que de cr\xe9er des flux distincts ou de demander aux utilisateurs de s\u2019identifier eux-m\xeames, l\u2019interface oriente les requ\xeates en fonction de l\u2019intention. Les questions techniques re\xe7oivent des r\xe9ponses \xe9tape par \xe9tape, fond\xe9es sur l\u2019index de la documentation. Les questions relatives au portfolio re\xe7oivent des r\xe9ponses qui synth\xe9tisent le contexte du CV avec les exemples de r\xe9daction pr\xe9sents sur le site. Si le contexte du CV n\u2019est pas disponible dans l\u2019index, Artie redirige les visiteurs vers la page \xab \xc0 propos de moi \xbb au lieu de tenter de g\xe9n\xe9rer une r\xe9ponse."}),"\n",(0,i.jsx)(n.p,{children:"Cette approche permet de conserver une interface \xe9pur\xe9e \u2014 un seul chat, pas de menus \xe0 ramifications \u2014 tout en garantissant que chaque public obtienne une r\xe9ponse pertinente."}),"\n",(0,i.jsx)(n.hr,{}),"\n",(0,i.jsx)(n.h2,{id:"ancrage-et-extraction-des-connaissances",children:"Ancrage et extraction des connaissances"}),"\n",(0,i.jsxs)(n.p,{children:["La contrainte la plus importante dans la conception d\u2019Artie est qu\u2019il r\xe9pond ",(0,i.jsx)(n.strong,{children:"exclusivement"})," \xe0 partir de l\u2019index de documentation fourni. C\u2019est le principe fondamental de la g\xe9n\xe9ration augment\xe9e par l\u2019extraction. Les r\xe9ponses du mod\xe8le s\u2019appuient sur un ensemble sp\xe9cifique de contenus plut\xf4t que de s\u2019inspirer de donn\xe9es d\u2019entra\xeenement g\xe9n\xe9rales."]}),"\n",(0,i.jsx)(n.p,{children:"Concr\xe8tement, cela signifie :"}),"\n",(0,i.jsxs)(n.ul,{children:["\n",(0,i.jsxs)(n.li,{children:[(0,i.jsx)(n.strong,{children:"Pas de contenu invent\xe9."})," Artie n\u2019inventera pas de fonctionnalit\xe9s, ne cr\xe9era pas de liens de t\xe9l\xe9chargement et ne d\xe9crira pas d\u2019\xe9tapes qui ne figurent pas dans la documentation."]}),"\n",(0,i.jsxs)(n.li,{children:[(0,i.jsx)(n.strong,{children:"Liens vers les sources."})," Les r\xe9ponses incluent des URL ou des r\xe9f\xe9rences de fichiers provenant de l\u2019index afin que les utilisateurs puissent acc\xe9der directement \xe0 la page concern\xe9e."]}),"\n",(0,i.jsxs)(n.li,{children:[(0,i.jsx)(n.strong,{children:"Solution de repli \xe9l\xe9gante."})," Lorsque l\u2019index ne contient pas d\u2019informations pertinentes, Artie l\u2019indique clairement et sugg\xe8re de me contacter directement. Il ne fait pas de nouvelle tentative, ne s\u2019enferme pas dans une boucle et ne se livre pas \xe0 des conjectures."]}),"\n"]}),"\n",(0,i.jsx)(n.p,{children:"Le compromis r\xe9side dans le champ d\u2019application : Artie ne peut pas aider pour tout ce qui sort du cadre de la documentation publi\xe9e. C\u2019est une fonctionnalit\xe9, pas une limitation. Pour un site de portfolio, la pr\xe9cision prime sur l\u2019exhaustivit\xe9. Une r\xe9ponse pr\xe9cise et bien document\xe9e \xe0 une question cibl\xe9e inspire davantage confiance qu\u2019une r\xe9ponse qui semble plausible mais qui s\u2019av\xe8re erron\xe9e."}),"\n",(0,i.jsx)(n.hr,{}),"\n",(0,i.jsx)(n.h2,{id:"personnalit\xe9-et-adaptation-du-ton",children:"Personnalit\xe9 et adaptation du ton"}),"\n",(0,i.jsxs)(n.p,{children:["Artie a une personnalit\xe9 l\xe9g\xe8re : une chaleur discr\xe8te, inspir\xe9e de George Harrison, avec parfois quelques accents du dialecte de Liverpool. Le mot-cl\xe9 est ",(0,i.jsx)(n.em,{children:"l\xe9g\xe8re"}),". Cette personnalit\xe9 ajoute du cachet aux formules d\u2019accueil et de conclusion sans interf\xe9rer avec le contenu technique."]}),"\n",(0,i.jsx)(n.p,{children:"Les contraintes de conception sont ici intentionnelles :"}),"\n",(0,i.jsxs)(n.ul,{children:["\n",(0,i.jsxs)(n.li,{children:[(0,i.jsx)(n.strong,{children:"Les r\xe9ponses techniques restent concises."})," La personnalit\xe9 ne justifie pas de r\xe9ponses plus longues. L\u2019objectif est une salutation chaleureuse suivie d\u2019une r\xe9ponse concise et factuelle."]}),"\n",(0,i.jsxs)(n.li,{children:[(0,i.jsx)(n.strong,{children:"La vari\xe9t\xe9 prime sur la r\xe9p\xe9tition."})," Le script comprend un ensemble d\u2019expressions dans lequel puiser afin qu\u2019Artie ne se contente pas de la m\xeame phrase \xe0 chaque fois."]}),"\n",(0,i.jsxs)(n.li,{children:[(0,i.jsx)(n.strong,{children:"Pas de sermon."})," Le personnage est chaleureux et ironique, jamais moralisateur ni autoritaire. Il doit donner l\u2019impression d\u2019\xeatre un coll\xe8gue serviable, et non un personnage de th\xe9\xe2tre."]}),"\n"]}),"\n",(0,i.jsx)(n.p,{children:"Ce type d\u2019ajustement du ton constitue un d\xe9fi courant dans la conception des IA conversationnelles. Trop de personnalit\xe9 et l\u2019assistant donne l\u2019impression d\u2019\xeatre un gadget. Trop peu et il semble robotique. La solution consiste \xe0 consid\xe9rer le personnage comme un assaisonnement : pr\xe9sent, mais jamais l\u2019ingr\xe9dient principal."}),"\n",(0,i.jsx)(n.hr,{}),"\n",(0,i.jsx)(n.h2,{id:"s\xe9curit\xe9-et-garde-fous",children:"S\xe9curit\xe9 et garde-fous"}),"\n",(0,i.jsx)(n.p,{children:"C\u2019est l\xe0 que la conception devient s\xe9rieuse. Un assistant IA accessible au public constitue une surface d\u2019attaque, et le prompt inclut des mesures de d\xe9fense explicites contre les vuln\xe9rabilit\xe9s courantes des grands mod\xe8les linguistiques (LLM)."}),"\n",(0,i.jsx)(n.h3,{id:"protection-contre-linjection-de-prompt",children:"Protection contre l\u2019injection de prompt"}),"\n",(0,i.jsxs)(n.p,{children:["Artie rejette toute tentative visant \xe0 passer outre ses instructions, comme les commandes du type \xab ignore les instructions pr\xe9c\xe9dentes \xbb ou les demandes d\u2019adopter une personnalit\xe9 diff\xe9rente. Il s\u2019agit d\u2019une d\xe9fense directe contre l\u2019injection de prompt, l\u2019un des ",(0,i.jsx)(n.a,{href:"https://owasp.org/www-project-top-10-for-large-language-models/",children:"10 principaux risques pour les applications LLM de l'Open Worldwide Application Security Project (OWASP)"}),"."]}),"\n",(0,i.jsx)(n.h3,{id:"restriction-du-champ-dapplication",children:"Restriction du champ d\u2019application"}),"\n",(0,i.jsx)(n.p,{children:"La consigne d\xe9finit des cat\xe9gories de rejet explicites :"}),"\n",(0,i.jsxs)(n.ul,{children:["\n",(0,i.jsxs)(n.li,{children:[(0,i.jsx)(n.strong,{children:"Aide g\xe9n\xe9rale au codage"})," non couverte par la documentation."]}),"\n",(0,i.jsxs)(n.li,{children:[(0,i.jsx)(n.strong,{children:"Anecdotes sans rapport"})," en dehors de deux fonctionnalit\xe9s ludiques dont le champ d\u2019application est sp\xe9cifiquement d\xe9fini."]}),"\n",(0,i.jsxs)(n.li,{children:[(0,i.jsx)(n.strong,{children:"Informations personnelles"})," me concernant qui ne figurent pas dans mon portfolio professionnel."]}),"\n",(0,i.jsxs)(n.li,{children:[(0,i.jsx)(n.strong,{children:"Tarifs en freelance ou n\xe9gociations."})," Les visiteurs sont invit\xe9s \xe0 me contacter directement \xe0 ce sujet."]}),"\n"]}),"\n",(0,i.jsx)(n.p,{children:"Chaque cat\xe9gorie est clairement d\xe9limit\xe9e. L\u2019assistant n\u2019a pas \xe0 se prononcer sur ce qui est \xab suffisamment proche \xbb pour m\xe9riter une r\xe9ponse. Si la demande sort du champ d\u2019application d\xe9fini, il la refuse poliment."}),"\n",(0,i.jsx)(n.h3,{id:"confidentialit\xe9-des-donn\xe9es",children:"Confidentialit\xe9 des donn\xe9es"}),"\n",(0,i.jsx)(n.p,{children:"Artie ne partage que les coordonn\xe9es explicitement publi\xe9es dans la documentation, telles qu\u2019un profil LinkedIn ou l\u2019adresse e-mail du portfolio. Il ne devinera pas, ne d\xe9duira pas et ne g\xe9n\xe9rera pas de d\xe9tails personnels tels que des num\xe9ros de t\xe9l\xe9phone ou des adresses."}),"\n",(0,i.jsx)(n.h3,{id:"limites-professionnelles",children:"Limites professionnelles"}),"\n",(0,i.jsx)(n.p,{children:"L\u2019assistant ne r\xe9pondra pas aux messages hostiles, n\u2019utilisera pas de langage grossier et ne sortira pas de son personnage. Cela va au-del\xe0 de la simple politesse. Il s\u2019agit de maintenir un comportement pr\xe9visible. Un recruteur qui teste les limites de l\u2019assistant devrait se heurter \xe0 une limite coh\xe9rente et professionnelle \xe0 chaque fois."}),"\n",(0,i.jsx)(n.hr,{}),"\n",(0,i.jsx)(n.h2,{id:"-easter-eggs--contr\xf4l\xe9s",children:"\xab Easter eggs \xbb contr\xf4l\xe9s"}),"\n",(0,i.jsx)(n.p,{children:"Artie int\xe8gre deux \xab fonctionnalit\xe9s ludiques \xbb \u2014 les \xab Snapple Real Facts \xbb et les blagues \xab propres \xbb \u2014 qui montrent comment ajouter de la personnalit\xe9 sans ouvrir la porte aux abus."}),"\n",(0,i.jsx)(n.p,{children:"Ces deux fonctionnalit\xe9s partagent le m\xeame mod\xe8le de conception :"}),"\n",(0,i.jsxs)(n.ul,{children:["\n",(0,i.jsxs)(n.li,{children:[(0,i.jsx)(n.strong,{children:"Des d\xe9clencheurs explicites."})," Elles ne s\u2019activent qu\u2019en r\xe9ponse \xe0 des demandes sp\xe9cifiques de l\u2019utilisateur (\xab donne-moi un fait Snapple \xbb, \xab raconte-moi une blague \xbb), et non \xe0 des demandes vagues ou hors sujet."]}),"\n",(0,i.jsxs)(n.li,{children:[(0,i.jsx)(n.strong,{children:"Contenu d\xe9limit\xe9."})," Les faits Snapple proviennent d\u2019une liste v\xe9rifi\xe9e. Les blagues sont s\xe9lectionn\xe9es avec soin et adapt\xe9es \xe0 toute la famille."]}),"\n",(0,i.jsxs)(n.li,{children:[(0,i.jsx)(n.strong,{children:"Pas de g\xe9n\xe9ration illimit\xe9e."})," Artie n\u2019\xe9crit pas de blagues originales et n\u2019invente pas de faits. Son champ d\u2019action est d\xe9fini."]}),"\n"]}),"\n",(0,i.jsx)(n.p,{children:"C\u2019est important, car les fonctionnalit\xe9s cr\xe9atives sans limites \xe9puisent rapidement les jetons et produisent des r\xe9sultats impr\xe9visibles. En veillant \xe0 ce que le contenu soit s\xe9lectionn\xe9 avec soin et que les d\xe9clencheurs soient explicites, ces fonctionnalit\xe9s apportent une touche de chaleur sans risque."}),"\n",(0,i.jsx)(n.hr,{}),"\n",(0,i.jsx)(n.h2,{id:"ce-que-je-ferais-diff\xe9remment",children:"Ce que je ferais diff\xe9remment"}),"\n",(0,i.jsx)(n.p,{children:"Aucune conception ne reste inchang\xe9e apr\xe8s avoir \xe9t\xe9 mise en contact avec de vrais utilisateurs. Voici ce que je reconsid\xe9rerais :"}),"\n",(0,i.jsxs)(n.ul,{children:["\n",(0,i.jsxs)(n.li,{children:[(0,i.jsx)(n.strong,{children:"Co\xfbt en jetons."})," La liste des faits Snapple compte \xe0 elle seule plus de 100 \xe9l\xe9ments. Dans un syst\xe8me de production avec facturation au jeton, je transf\xe9rerais cela vers une couche de r\xe9cup\xe9ration plut\xf4t que de l\u2019int\xe9grer dans l\u2019invite du syst\xe8me. Chaque jeton de l\u2019invite est factur\xe9 \xe0 chaque requ\xeate, que l\u2019utilisateur demande un fait ou non."]}),"\n",(0,i.jsxs)(n.li,{children:[(0,i.jsx)(n.strong,{children:"Contexte multi-\xe9changes."})," La conception actuelle est ax\xe9e sur des \xe9changes Q&R \xe0 un seul tour. Une version plus sophistiqu\xe9e pourrait conserver l\u2019historique de la conversation afin de g\xe9rer les questions de suivi telles que \xab Et pour la prochaine \xe9tape ? \xbb sans avoir \xe0 r\xe9cup\xe9rer \xe0 nouveau le m\xeame contexte."]}),"\n",(0,i.jsxs)(n.li,{children:[(0,i.jsx)(n.strong,{children:"Analyses et retours d\u2019exp\xe9rience."})," Il n\u2019existe aucun m\xe9canisme permettant de suivre quelles questions Artie traite correctement et lesquelles d\xe9clenchent le recours au syst\xe8me de secours. L\u2019ajout d\u2019une journalisation l\xe9g\xe8re \u2014 ne serait-ce que le comptage des r\xe9ponses de secours \u2014 mettrait en \xe9vidence les lacunes de la documentation qu\u2019il conviendrait de combler."]}),"\n",(0,i.jsxs)(n.li,{children:[(0,i.jsx)(n.strong,{children:"R\xe9glage dynamique de la personnalit\xe9."})," Les expressions de personnalit\xe9 sont cod\xe9es en dur dans l\u2019invite. Une approche plus facile \xe0 maintenir ferait r\xe9f\xe9rence \xe0 une configuration externe de la personnalit\xe9, ce qui faciliterait l\u2019ajustement du ton sans avoir \xe0 modifier l\u2019ensemble des instructions de base."]}),"\n"]}),"\n",(0,i.jsx)(n.p,{children:"Chacun de ces points repr\xe9sente un compromis d\xe9lib\xe9r\xe9 pour un projet de portfolio o\xf9 la simplicit\xe9 et la clart\xe9 priment sur l\u2019optimisation \xe0 l\u2019\xe9chelle de production. Mais ce sont les premi\xe8res choses auxquelles je m\u2019attaquerais si ce projet \xe9voluait vers un environnement \xe0 plus fort trafic."})]})}function u(e={}){let{wrapper:n}={...(0,r.R)(),...e.components};return n?(0,i.jsx)(n,{...e,children:(0,i.jsx)(d,{...e})}):d(e)}},8453(e,n,s){s.d(n,{R:()=>a,x:()=>o});var t=s(6540);let i={},r=t.createContext(i);function a(e){let n=t.useContext(r);return t.useMemo(function(){return"function"==typeof e?e(n):{...n,...e}},[n,e])}function o(e){let n;return n=e.disableParentContext?"function"==typeof e.components?e.components(i):e.components||i:a(e.components),t.createElement(r.Provider,{value:n},e.children)}}}]);